- 상태 배지로 프로젝트 진행 상태 표시
- 수상 이미지는 Next.js Image로 최적화

구현 가이드:

1. **연구활동 컴포넌트 (src/components/sections/research-section.tsx):**
```typescript
'use client'

import { useResearch } from '@/lib/hooks/use-portfolio-data'
import { Card, CardContent } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { FlaskConical, ExternalLink, FileText } from 'lucide-react'

export function ResearchSection() {
  const { research, isLoading } = useResearch()

  if (isLoading) {
    return <ResearchSkeleton />
  }

  if (!research || research.length === 0) {
    return <div className="text-center text-gray-500">연구활동 데이터가 없습니다.</div>
  }

  const sortedResearch = [...research].sort((a, b) => a.sort_order - b.sort_order)

  return (
    <div className="grid gap-4 md:grid-cols-2">
      {sortedResearch.map((item) => (
        <Card key={item.id}>
          <CardContent className="pt-6">
            <div className="flex items-start gap-3">
              <div className="rounded-full bg-primary/10 p-2">
                <FlaskConical className="h-5 w-5 text-primary" />
              </div>
              <div className="flex-1">
                <h3 className="font-bold">{item.name}</h3>
                {item.description && (
                  <p className="mt-2 text-sm text-muted-foreground">{item.description}</p>
                )}
                <div className="mt-4 flex gap-2">
                  {item.url && (
                    <Button variant="outline" size="sm" asChild>
                      <a href={item.url} target="_blank" rel="noopener noreferrer">
                        상세보기
                        <ExternalLink className="ml-2 h-3 w-3" />
                      </a>
                    </Button>
                  )}
                  {item.document_url && (
                    <Button variant="outline" size="sm" asChild>
                      <a href={item.document_url} target="_blank" rel="noopener noreferrer">
                        문서 보기
                        <FileText className="ml-2 h-3 w-3" />
                      </a>
                    </Button>
                  )}
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  )
}

function ResearchSkeleton() {
  return (
    <div className="grid gap-4 md:grid-cols-2">
      {[1, 2].map((i) => (
        <div key={i} className="h-32 animate-pulse rounded-lg bg-gray-200" />
      ))}
    </div>
  )
}
```

